tool.command:
@PREPARE_ENV@
@PREPARE_CORPUS@
@PREPARE_TOKENIZER@

## 3. Run Tokenize
## Syntax: mfa tokenize [OPTIONS] CORPUS_DIRECTORY TOKENIZER_PATH OUTPUT_DIRECTORY
mfa tokenize
    corpus_dir
    '$tok_arg'
    output_dir
    --job_name 'mfa_tokenize_job'
    --num_jobs "\${GALAXY_SLOTS:-1}"

## 4. Collect the audio files next to the tokenized transcripts so that
## both end up in the output archive (see macro for details).
@COLLECT_AUDIO@

@ZIP_OUTPUT@
